def make(n):
    # produce n versions with 1,2,…,n dot‑separated components
    return [[".".join(str(i) for i in range(1, k+1))] for k in range(1, n+1)]

def make(n):
    # produce n versions with 1,2,...,n dot‑separated segments
    return [[".".join(str(i) for i in range(1, seg+1))] for seg in range(1, n+1)]

def make(n):
    chunks = []
    for i in range(1, n+1):
        chunks.append(str(i).zfill(i))
    version = '.'.join(chunks) + 'c5'
    return [(version,)]
